'use strict'

/**
 * {
 *    '-a' : {
 *      name: 'a',
 *      type: 'number|string|int|float|bool',
 *      min: 0,
 *      max: 100,
 *      match: RegExp,
 *      default : any
 *    },
 *    {
 *      '--port=' : {
 *        name : 'port',
 *        type : 'int',
 *        min: 2000,
 *        max: 5000,
 *        default: 3456
 *      }
 *    }
 * }
 * 
 */

function setVal (a, ainfo, obj, next) {

  if (ainfo.type && ['int', 'float', 'number'].indexOf(ainfo.type) >= 0) {
      if (isNaN(next)) {
        return {
          ok: false,
          errmsg: `${a} 类型错误，要求参数必须是数字类型：${next}`
        }
      }

      if (ainfo.type === 'int' || ainfo.type === 'number') {
        next = parseInt(next)
      } else {
        next = parseFloat(next)
      }
  }

  if (ainfo.min !== undefined) {
    if (next < ainfo.min) {
      return {
        ok: false,
        errmsg: `${a} 数值不能低于 ${ainfo.min}`
      }
    }
  }

  if (ainfo.max !== undefined) {
    if (next > ainfo.max) {
      return {
        ok: false,
        errmsg: `${a} 数值不能大于 ${ainfo.max}`
      }
    }
  }

  if (ainfo.match && ainfo.match instanceof RegExp) {
    if (!ainfo.match.test(next)) {
      return {
        ok: false,
        errmsg: `${a} 数值无法匹配 ${next}`
      }
    }
  }

  let val = next

  if (ainfo.callback && typeof ainfo.callback === 'function') {
    val = ainfo.callback(next)
    if (val === undefined) val = next
  }

  obj[ ainfo.name || a ] = val

  return {
    ok: true,
    errmsg: ''
  }

}

function checkAndSet (a, ainfo, obj, next) {

  if (typeof ainfo === 'boolean') {
    obj[a] = true
    return {
      ok: true,
      errmsg: '',
      op: 'none'
    }
  }

  if (ainfo.type === 'bool' || ainfo.type === 'boolean') {
    obj[ ainfo.name || a ] = true

    return {
      ok: true,
      errmsg : '',
      op: 'none'
    }
  }

  if (next === null) {
    return {
      ok: false,
      errmsg: `${a} 必须携带参数。`
    }
  }

  let r = setVal(a, ainfo, obj, next)

  if (!r.ok && ainfo.default !== undefined) {
    r.ok = true
  }

  if (r.ok) {
    r.op = 'next'

    if (a[a.length - 1] === '=') {
      r.op = 'none'
    }
  }

  return r
}

function parseArgv (opts = null, obj = null) {
  if (!opts) opts = {}

  if (obj === null) obj = {}

  let tmp_val

  for (let k in opts) {
    if (typeof opts[k] !== 'object' || opts[k].toString() !== '[object Object]') {
      opts[k] = !!opts[k]
    } else if (opts[k].type === undefined) {

      if (k.indexOf('=') > 0) {
        opts[k].type = 'string'
      } else if (opts[k].match || opts[k].callback) {
        opts[k].type = 'string'
      } else {
          if (opts[k].min !== undefined || opts[k].max !== undefined) {
            opts[k].type = 'int'
          } else if (opts[k].default !== undefined) {
            tmp_val = typeof opts[k].default
            if (tmp_val === 'number') {
              opts[k].type = 'number'
            } else {
              opts[k].type = 'string'
            }
          } else {
            opts[k].type = 'bool'
          }
      }

    }

    if (typeof opts[k] === 'boolean') {
      obj[k] = false
    } else if (opts[k].type === 'bool' || opts[k].type === 'boolean') {
      obj[ opts[k].name || k ] = false
    } else if (opts[k].default !== undefined) {
      obj[ opts[k].name || k ] = opts[k].default
    }

  }

  let a
  let next
  let next_end = process.argv.length - 1
  let r = ''
  let i = 2
  let ind = 0

  while (i < process.argv.length) {
    a = process.argv[i]
    
    next = i < next_end ? process.argv[i+1] : null

    ind = a.indexOf('=')

    if (ind > 0) {
      a = a.substring(0, ind+1)
      next = process.argv[i].substring(ind+1)
    }

    if (opts[a]) {
      r = checkAndSet(a, opts[a], obj, next)
      if (!r.ok) {
        return r
      }

      if (r.op === 'next') {
        i += 2
        continue
      }

    } else {
      obj[a] = true
    }

    i++
  }

  return {
    ok: true,
    errmsg: '',
    args: obj
  }
}

module.exports = parseArgv
